      "      .topbar { flex-wrap: wrap; }",
      "      .top-actions { width: 100%; margin-left: 0; }",
      "    }",
      "    @media (max-width: 780px) {",
      "      .workspace { display: block; padding: 8px; }",
      "      .left-panel, .right-panel { position: static; max-height: none; margin-bottom: 9px; }",
      "      .unit-list { max-height: 180px; }",
      "      .main-panel { min-height: auto; padding: 14px; margin-bottom: 9px; }",
      "      .view-top { display: block; }",
      "      .controls { justify-content: flex-start; margin-top: 11px; }",
      "      .stats, .form-grid, .library-grid, .library-toolbar, .split-row { grid-template-columns: 1fr; }",
      "      .sentence-role { grid-template-columns: 1fr; }",
      "      .brand-sub { display: none; }",
      "      :root { --practice-font: 17px; }",
      "    }",
      "",
      "    /* Writing Assistant 0.5.0 public UI */",
      "    .topbar {",
      "      display: grid;",
      "      grid-template-columns: minmax(250px,1fr) auto minmax(250px,1fr);",
      "      gap: 22px;",
      "      padding: 11px max(20px, calc((100vw - 1560px) / 2));",
      "      background: rgba(249,250,253,.92);",
      "    }",
      "    .brand { min-width: 0; }",
      "    .brand-title-row { display: flex; align-items: center; gap: 8px; }",
      "    .brand-title { font-size: 16px; letter-spacing: -.02em; }",
      "    .version-badge { padding: 3px 7px; border: 1px solid #d9e0ee; border-radius: 999px; color: #778195; background: #fff; font-size: 9px; font-weight: 800; }",
      "    .lab-tabs { justify-self: center; }",
      "    .top-actions { width: auto; margin-left: 0; flex-wrap: nowrap; }",
      "    .local-status { display: inline-flex; align-items: center; gap: 7px; white-space: nowrap; color: #667085; font-size: 11px; font-weight: 750; }",
      "    .status-dot { width: 8px; height: 8px; border-radius: 50%; background: #22c55e; box-shadow: 0 0 0 4px rgba(34,197,94,.11); }",
      "    .data-menu-wrap { position: relative; }",
      "    .data-menu-trigger { padding-inline: 14px; }",
      "    .data-menu { position: absolute; top: calc(100% + 9px); right: 0; z-index: 80; width: min(330px, calc(100vw - 28px)); padding: 9px; border: 1px solid var(--line); border-radius: 16px; background: rgba(255,255,255,.98); box-shadow: 0 22px 65px rgba(16,24,40,.16); backdrop-filter: blur(18px); }",
      "    .data-menu[hidden] { display: none; }",
      "    .data-menu-head { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; padding: 8px 9px 11px; border-bottom: 1px solid var(--line); }",
      "    .data-menu-head strong { font-size: 13px; }",
      "    .data-menu-head span { color: var(--muted); font-size: 9px; text-align: right; }",
      "    .menu-action { width: 100%; display: grid; grid-template-columns: 25px 1fr; gap: 8px; align-items: start; padding: 10px 9px; border: 0; border-radius: 10px; color: var(--text); background: transparent; text-align: left; }",
      "    .menu-action:hover { background: #f5f7fb; }",
      "    .menu-action > span:first-child { display: grid; place-items: center; width: 24px; height: 24px; border-radius: 8px; color: var(--primary); background: var(--primary-soft); font-weight: 900; }",
      "    .menu-action strong, .menu-action small { display: block; }",
      "    .menu-action strong { font-size: 11px; }",
      "    .menu-action small { margin-top: 2px; color: var(--muted); font-size: 9px; line-height: 1.45; }",
      "    .menu-divider { height: 1px; margin: 5px 8px; background: var(--line); }",
      "    .danger-text strong { color: var(--bad); }",
      "    .danger-text > span:first-child { color: var(--bad); background: var(--bad-soft); }",
      "",
      "    .workspace { width: min(1560px,100%); margin: 0 auto; grid-template-columns: minmax(200px,230px) minmax(560px,1fr) minmax(250px,310px); gap: 13px; padding: 16px 18px 22px; }",
      "    .panel { border-color: rgba(219,225,236,.96); }",
      "    .main-panel { padding: 22px; }",
      "    .left-panel, .right-panel { top: 76px; }",
      "    .target-card, .sub-card { background: #fff; }",
      "    .writer { box-shadow: inset 0 1px 2px rgba(16,24,40,.025); }",
      "    .view-top h1, .library-hero h1 { letter-spacing: -.025em; }",
      "",
      "    body[data-lab-active=\"library\"] .workspace { display: block; width: min(1220px,100%); }",
      "    body[data-lab-active=\"library\"] .left-panel,",
      "    body[data-lab-active=\"library\"] .right-panel { display: none; }",
      "    body[data-lab-active=\"library\"] .main-panel { min-height: calc(100vh - 102px); }",
      "    .library-hero { display: flex; justify-content: space-between; align-items: flex-end; gap: 28px; padding-bottom: 19px; border-bottom: 1px solid var(--line); }",
      "    .library-hero h1 { margin: 6px 0 7px; font-size: 25px; }",
      "    .library-hero p { max-width: 690px; margin: 0; color: var(--muted); font-size: 12px; line-height: 1.7; }",
      "    .library-notice-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin: 15px 0; }",
      "    .notice-card { display: grid; grid-template-columns: 36px 1fr; gap: 10px; align-items: start; padding: 13px 14px; border: 1px solid var(--line); border-radius: 13px; background: #fafbfe; }",
      "    .notice-icon { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 10px; color: var(--primary); background: var(--primary-soft); font-weight: 900; }",
      "    .notice-card strong { font-size: 12px; }",
      "    .notice-card p { margin: 4px 0 0; color: var(--muted); font-size: 10px; line-height: 1.55; }",
      "    .library-toolbar { grid-template-columns: 1fr 190px auto; margin: 16px 0 13px; }",
      "    .library-grid { grid-template-columns: repeat(3,minmax(0,1fr)); gap: 12px; }",
      "    .library-card { display: flex; flex-direction: column; min-height: 300px; padding: 17px; transition: transform .15s ease, box-shadow .15s ease, border-color .15s ease; }",
      "    .library-card:hover { transform: translateY(-2px); border-color: #cbd5e7; box-shadow: 0 14px 36px rgba(24,39,75,.08); }",
      "    .library-card h3 { font-size: 16px; letter-spacing: -.015em; }",
      "    .library-preview { flex: 1; -webkit-line-clamp: 5; }",
      "    .library-actions { margin-top: auto; padding-top: 4px; }",
      "    .library-about { margin-top: 18px; border: 1px solid var(--line); border-radius: 14px; background: #fbfcff; }",
      "    .library-about summary { cursor: pointer; padding: 14px 16px; color: #485469; font-size: 11px; font-weight: 800; }",
      "    .library-about-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 22px; padding: 0 16px 17px; }",
      "    .library-about-grid h3 { margin: 3px 0 9px; font-size: 12px; }",
      "    .resource-links.compact { grid-template-columns: 1fr 1fr; }",
      "",
      "    @media (max-width: 1260px) {",
      "      .topbar { grid-template-columns: 1fr auto; }",
      "      .lab-tabs { grid-column: 1 / -1; grid-row: 2; justify-self: center; }",
      "      .top-actions { justify-self: end; }",
      "      .workspace { grid-template-columns: 210px minmax(500px,1fr); }",
      "      .right-panel { position: static; max-height: none; grid-column: 1 / -1; }",
      "      .library-grid { grid-template-columns: repeat(2,minmax(0,1fr)); }",
      "    }",
      "    @media (max-width: 820px) {",
      "      .topbar { display: flex; flex-wrap: wrap; gap: 10px; padding: 10px 12px; }",
      "      .brand { flex: 1 1 auto; }",
      "      .lab-tabs { width: 100%; order: 3; overflow-x: auto; justify-content: stretch; }",
      "      .lab-tab { flex: 1 0 auto; }",
      "      .local-status { display: none; }",
      "      .workspace { width: 100%; padding: 9px; }",
      "      .main-panel { padding: 15px; }",
      "      .library-hero { display: block; }",
      "      .library-hero .controls { margin-top: 14px; }",
      "      .library-notice-grid, .library-about-grid, .library-grid { grid-template-columns: 1fr; }",
      "      .resource-links.compact { grid-template-columns: 1fr; }",
      "    }",
