      "/* Writing Assistant 0.7.0 · folder library and long-text workspace */",
      ".library-browser-layout {",
      "  display: grid;",
      "  grid-template-columns: minmax(190px, 230px) minmax(0, 1fr);",
      "  gap: 16px;",
      "  align-items: start;",
      "  margin-top: 16px;",
      "}",
      ".folder-sidebar {",
      "  position: sticky;",
      "  top: 80px;",
      "  max-height: calc(100vh - 116px);",
      "  overflow: auto;",
      "  border: 1px solid var(--line);",
      "  border-radius: 15px;",
      "  background: #fbfcff;",
      "}",
      ".folder-sidebar-head {",
      "  display: flex;",
      "  justify-content: space-between;",
      "  align-items: baseline;",
      "  gap: 8px;",
