      "      format: 'epub',",
      "      title: title,",
      "      source: author ? author + ' · Local EPUB' : 'Local EPUB · ' + file.name,",
      "      license: 'Personal study; verify source copyright',",
      "      tags: unique(['epub', 'book', author]),",
      "      warnings: warnings,",
      "      chapters: chapters,",
