      "    if (twoColumnPages) warnings.push('检测到 ' + twoColumnPages + ' 页可能采用双栏排版；已尝试按左栏后右栏排序，但保存前仍应抽查正文。');",
      "    if (!trimmed(totalText)) throw new Error('PDF 中没有提取到文字。扫描版 PDF 请等待后续本地 OCR 连接器。');",
