      "    byId('aiStorageMode').value = config.storageMode || 'session';",
      "    byId('aiAnthropicVersion').value = config.anthropicVersion || '2023-06-01';",
      "    byId('aiApiKey').value = runtimeApiKey || sessionKey() || '';",
      "    byId('aiVaultPassword').value = '';",
